'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isSameValuef = require( '@stdlib/number/float32/base/assert/is-same-value' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var expm1f = require( './../lib' );


// FIXTURES //

var mediumNegative = require( './fixtures/julia/medium_negative.json' );
var mediumPositive = require( './fixtures/julia/medium_positive.json' );
var smallNegative = require( './fixtures/julia/small_negative.json' );
var smallPositive = require( './fixtures/julia/small_positive.json' );
var tiny = require( './fixtures/julia/tiny.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof expm1f, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes `exp(x) - 1` (medium negative values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = mediumNegative.x;
	expected = mediumNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = expm1f( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes `exp(x) - 1` (medium positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = mediumPositive.x;
	expected = mediumPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = expm1f( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes `exp(x) - 1` (small negative values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = smallNegative.x;
	expected = smallNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = expm1f( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes `exp(x) - 1` (small positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = smallPositive.x;
	expected = smallPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = expm1f( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes `exp(x) - 1` (tiny values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = tiny.x;
	expected = tiny.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = expm1f( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isSameValuef( y, e ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var v = expm1f( +0.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var v = expm1f( -0.0 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = expm1f( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var v = expm1f( PINF );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-1` if provided `-infinity`', function test( t ) {
	var v = expm1f( NINF );
	t.strictEqual( v, -1.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided a value which exceeds the overflow threshold', function test( t ) {
	var v;

	v = expm1f( 89.0 );
	t.strictEqual( v, PINF, 'returns expected value' );

	v = expm1f( 100.0 );
	t.strictEqual( v, PINF, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if provided a large negative value', function test( t ) {
	var v;

	v = expm1f( -50.0 );
	t.strictEqual( v, -1.0, 'returns expected value' );

	v = expm1f( -100.0 );
	t.strictEqual( v, -1.0, 'returns expected value' );

	t.end();
});
